package org.apache.commons.math.optimization;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.LocalizedFormats;
import org.apache.commons.math3.optim.univariate.UnivariateRealFunction;
import org.apache.commons.math3.optim.univariate.UnivariateRealOptimizer;
import org.apache.commons.math3.random.JDKRandomGenerator;
import org.apache.commons.math3.random.RandomGenerator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

public class MultiStartUnivariateRealOptimizer_getFunctionValue_TriageGen5Test {

    @Mock
    private UnivariateRealOptimizer mockOptimizer;

    @Mock
    private RandomGenerator mockGenerator;

    private MultiStartUnivariateRealOptimizer multiStartOptimizer;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        // The constructor requires a UnivariateRealOptimizer, number of starts, and a RandomGenerator
        multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 5, mockGenerator);
    }

    @Test
    public void testGetFunctionValue_ReturnsCorrectValue() {
        // Arrange
        double expectedValue = 42.0;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals("The getFunctionValue should return the value provided by the underlying optimizer.", 
                     expectedValue, actualValue, 1e-15);
    }

    @Test
    public void testGetFunctionValue_ReturnsNegativeValue() {
        // Arrange
        double expectedValue = -123.456;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals("The getFunctionValue should correctly return negative values.", 
                     expectedValue, actualValue, 1e-15);
    }

    @Test
    public void testGetFunctionValue_ReturnsZero() {
        // Arrange
        double expectedValue = 0.0;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals("The getFunctionValue should correctly return zero.", 
                     expectedValue, actualValue, 1e-15);
    }

    @Test
    public void testGetFunctionValue_ReturnsNaN() {
        // Arrange
        double expectedValue = Double.NaN;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals("The getFunctionValue should correctly return NaN if the underlying optimizer returns NaN.", 
                     expectedValue, actualValue, 0.0);
    }

    @Test
    public void testGetFunctionValue_ReturnsInfinity() {
        // Arrange
        double expectedValue = Double.POSITIVE_INFINITY;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals("The getFunctionValue should correctly return Infinity.", 
                     expectedValue, actualValue, 0.0);
    }
}
